function validate(input) {
  const [{ user_permissions = [] }] = input;
  if (!user_permissions.length) return 'user_permissions needs at least one row.';
  const ids = new Set();
  for (const [id, permissions] of user_permissions) {
    if (id === null) return 'Every row needs a user_id.';
    if (ids.has(id)) return `user_id ${id} appears twice.`;
    ids.add(id);
    if (permissions === null) return `User ${id} has null permissions; use 0 for none.`;
    if (permissions < 0 || permissions > 2147483647) return `User ${id}'s permissions must be from 0 to 2147483647.`;
  }
  return null;
}

