function generate(rand, size) {
  const small = size === 'small';
  const count = small ? 1 + Math.floor(rand() * 8) : 2000;
  // Distinct user ids from a wider pool, shuffled so they are neither consecutive nor sorted.
  const pool = Array.from({ length: small ? 20 : 4000 }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  // A random mask over the lowest `width` bits; width <= 31 keeps every value a non-negative INT.
  const mask = (width, chance) => { let m = 0; for (let bit = 0; bit < width; bit++) if (rand() < chance) m |= 1 << bit; return m; };
  const width = small ? 3 + Math.floor(rand() * 3) : 31;
  // Bits every user has (often none), and the bits users may hold on top of them.
  const shared = rand() < 0.6 ? mask(width, small ? 0.3 : 0.15) : 0;
  const optional = mask(width, small ? 0.8 : 0.5);
  const high = small && rand() < 0.2 ? 1 << 30 : 0;
  const user_permissions = [];
  for (let i = 0; i < count; i++) {
    let permissions = shared | (mask(width, 0.5) & optional);
    if (high && rand() < 0.7) permissions |= high;
    // Small tables sometimes hold a user with no rights or one with every right.
    if (small) { const roll = rand(); if (roll < 0.1) permissions = 0; else if (roll < 0.14) permissions = 2147483647; }
    user_permissions.push([pool[i], permissions]);
  }
  return [{ user_permissions }];
}
